 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, SRGBColorSpace, DoubleSide } = ctx.THREE;

  const node = new Group();

  const geometry = new PlaneGeometry(1.6, 1.0);
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    alphaTest: 0.02,
    side: DoubleSide,
    depthWrite: false
  });

  const plane = new Mesh(geometry, material);
  node.add(plane);

  let disposed = false;
  let texture = null;
  const timelines = [];

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;

  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      if (disposed) {
        tex.dispose();
        return;
      }
      texture = tex;
      texture.colorSpace = SRGBColorSpace;
      texture.needsUpdate = true;
      material.map = texture;
      material.needsUpdate = true;
    });
  }

  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    if (ctx.primitives?.[primitive.name]) {
      const result = ctx.primitives[primitive.name](node, primitive.params ?? {});
      if (result?.timeline) timelines.push(result.timeline);
    }
  }

  node.userData.handlers = {};
  node.userData.cleanup = () => {
    disposed = true;
    for (const tl of timelines) {
      if (tl && typeof tl.kill === 'function') tl.kill();
    }
    timelines.length = 0;
    if (texture) {
      texture.dispose();
      texture = null;
    }
    material.dispose();
    geometry.dispose();
    node.remove(plane);
  };

  return node;
}
